class Solution {
public:
    vector<int> lastVisitedCell(vector<vector<char>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        vector<vector<bool>> visited(m, vector<bool>(n, false));
        int r = 0, c = 0;
        visited[r][c] = true;
        while (true) {
            int nr = r, nc = c;
            char dir = grid[r][c];
            if (dir == 'L') nc--;
            else if (dir == 'R') nc++;
            else if (dir == 'U') nr--;
            else if (dir == 'D') nr++;
            // check bounds
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) break;
            // check visited
            if (visited[nr][nc]) break;
            // move
            r = nr; c = nc;
            visited[r][c] = true;
        }
        return {r, c};
    }
};
